import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Data Model & Storage","description":"","frontmatter":{},"headers":[],"relativePath":"guide/data-model-and-storage.md","filePath":"guide/data-model-and-storage.md","lastUpdated":1787151563000}'),s={name:"guide/data-model-and-storage.md"};function d(i,e,n,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="data-model-storage" tabindex="-1">Data Model &amp; Storage <a class="header-anchor" href="#data-model-storage" aria-label="Permalink to &quot;Data Model &amp; Storage&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>StrawMoneyBook 帳本資料存在本機 <strong>SQLite</strong>。Web 開發使用 sql.js（WASM），Android 使用 Capacitor SQLite + SQLCipher。Schema 透過 migration 版本遞增，Repository 層封裝所有 SQL 存取。</p><h2 id="儲存引擎" tabindex="-1">儲存引擎 <a class="header-anchor" href="#儲存引擎" aria-label="Permalink to &quot;儲存引擎&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>引擎</th><th>備註</th></tr></thead><tbody><tr><td>Web / 本機 dev</td><td>sql.js + IndexedDB persist</td><td>瀏覽器環境</td></tr><tr><td>Android</td><td><code>@capacitor-community/sqlite</code></td><td>SQLCipher 加密 DB 檔</td></tr><tr><td>Backend</td><td>better-sqlite3</td><td><code>collab-store.sqlite</code>，與 frontend 分離</td></tr></tbody></table><p>Frontend DB 初始化入口：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/services/bootstrap.service.js" target="_blank" rel="noreferrer"><code>bootstrap.service.js</code></a><br> Migration 目錄：<a href="https://github.com/StrawCoding/StrawMoneyBook/tree/main/frontend/src/core/db/migrations" target="_blank" rel="noreferrer"><code>frontend/src/core/db/migrations/</code></a></p><h2 id="核心實體關係-簡化" tabindex="-1">核心實體關係（簡化） <a class="header-anchor" href="#核心實體關係-簡化" aria-label="Permalink to &quot;核心實體關係（簡化）&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">erDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ledgers ||--o{ accounts : contains</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ledgers ||--o{ categories : contains</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ledgers ||--o{ transactions : contains</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  accounts ||--o{ transactions : posts_to</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  categories ||--o{ transactions : classifies</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  transactions ||--o{ loan_payments : may_link</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  transactions ||--o{ reimbursements : may_link</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ledgers ||--o{ budgets : has</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  budgets ||--o{ budget_items : contains</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ledgers ||--o{ loans : tracks</span></span></code></pre></div><p>帳本（ledger）是根實體；交易（transaction）連接帳戶、分類，並可延伸借貸、報銷、退款、轉帳雙腿等關聯列。</p><h2 id="repository-職責" tabindex="-1">Repository 職責 <a class="header-anchor" href="#repository-職責" aria-label="Permalink to &quot;Repository 職責&quot;">​</a></h2><p>目錄：<a href="https://github.com/StrawCoding/StrawMoneyBook/tree/main/frontend/src/core/repositories" target="_blank" rel="noreferrer"><code>frontend/src/core/repositories/</code></a></p><table tabindex="0"><thead><tr><th>Repository</th><th>主要資料</th></tr></thead><tbody><tr><td><code>ledger.repo.js</code></td><td>帳本 CRUD、排序</td></tr><tr><td><code>account.repo.js</code></td><td>帳戶、餘額、群組</td></tr><tr><td><code>category.repo.js</code></td><td>分類與群組</td></tr><tr><td><code>transaction.repo.js</code></td><td>交易 CRUD、軟刪、分頁查詢</td></tr><tr><td><code>budget.repo.js</code></td><td>預算期間、項目、共同池</td></tr><tr><td><code>loan.repo.js</code></td><td>借貸與還款</td></tr><tr><td><code>reimbursement.repo.js</code></td><td>報銷狀態</td></tr><tr><td><code>savings-jar.repo.js</code></td><td>存錢罐</td></tr><tr><td><code>bank-sync.repo.js</code></td><td>銀行連線設定</td></tr><tr><td><code>settings.repo.js</code></td><td>帳本級設定</td></tr><tr><td><code>base.repo.js</code></td><td>共用 helper</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">存取規則</p><p>View / Store <strong>不應</strong>直接寫 SQL。查詢類邏輯優先放 Service（如 <code>transaction-query.service.js</code>），持久化改 Repository。</p></div><h2 id="交易與-posting" tabindex="-1">交易與 Posting <a class="header-anchor" href="#交易與-posting" aria-label="Permalink to &quot;交易與 Posting&quot;">​</a></h2><p>複雜記帳（轉帳雙腿、借貸 setup、報銷入帳、信用卡還款 allocations）的純領域規則放在：</p><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/tree/main/frontend/src/core/domain/posting" target="_blank" rel="noreferrer"><code>core/domain/posting/</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/tree/main/frontend/src/core/domain/balance" target="_blank" rel="noreferrer"><code>core/domain/balance/</code></a></li></ul><p>Service 層（如 <code>transaction.service.js</code>）編排 posting 規則 + Repository 寫入。</p><h2 id="快照與匯入" tabindex="-1">快照與匯入 <a class="header-anchor" href="#快照與匯入" aria-label="Permalink to &quot;快照與匯入&quot;">​</a></h2><p>JSON 匯出 / 備份 / 共同帳本同步使用<strong>帳本快照</strong>格式。匯入前會：</p><ol><li><code>normalizeSharedLedgerSnapshot</code> — FK preserve（合成缺失父列，不刪減子列）</li><li><code>assertBackupJsonStructureImportable</code> — 結構與 CHECK 約束驗證</li></ol><p>詳見 <a href="/domains/sync-backup-shared-ledger.html">Sync, Backup &amp; Shared Ledger</a>。</p><h2 id="foreign-key-政策" tabindex="-1">Foreign Key 政策 <a class="header-anchor" href="#foreign-key-政策" aria-label="Permalink to &quot;Foreign Key 政策&quot;">​</a></h2><ul><li>全程 <code>PRAGMA foreign_keys=ON</code></li><li>禁止關閉 FK 或 silent no-op 修復</li><li>SQLite FK 錯誤轉為 typed <code>SQLITE_CONSTRAINT_FOREIGNKEY</code> + i18n 訊息</li></ul><h2 id="backend-資料-協作域" tabindex="-1">Backend 資料（協作域） <a class="header-anchor" href="#backend-資料-協作域" aria-label="Permalink to &quot;Backend 資料（協作域）&quot;">​</a></h2><p>Backend 的 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/backend/src/collab/store.js" target="_blank" rel="noreferrer"><code>collab/store.js</code></a> 管理：</p><ul><li><code>users</code>、<code>user_auth_providers</code></li><li><code>shared_ledgers</code> 與快照 blob</li><li>refresh session、邀請、referral</li></ul><p>與 frontend 本機 SQLite <strong>不是同一份檔案</strong>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/frontend-stack.html">Frontend Stack</a></li><li><a href="/domains/bookkeeping.html">Bookkeeping</a></li></ul>`,29)])])}const k=t(s,[["render",d]]);export{g as __pageData,k as default};
